import magic, uuid
ALLOWED = {'jpg','png','gif'}
file = request.files['file']
if file and file.filename.rsplit('.',1)[1].lower() in ALLOWED:
    mime = magic.from_buffer(file.read(2048), mime=True)
    if mime in {'image/jpeg','image/png','image/gif'}:
        file.seek(0)
        file.save('/var/www/uploads/' + uuid.uuid4().hex + '.jpg')
